+[%collapsible]
+====
+*Details* +
+${breaking.details.trim()}
+
+*Impact* +
+${breaking.impact.trim()}
+====
+<%
+        }
+
+        if (isNotable) {
+            print "// end::notable-breaking-changes[]\n"
+        }
+    }
+}
+%>
